import java.util.*;

class Solution {
    public int atLeast(int[] nums, int x) {
        TreeSet<Integer> ts = new TreeSet<>();
        for (int v : nums) ts.add(v);
        Integer c = ts.ceiling(x);
        return c == null ? -1 : c;
    }
}

