import java.util.*;

class Solution {
    public int floorOf(int[] keys, int q) {
        TreeMap<Integer, String> tm = new TreeMap<>();
        for (int k : keys) tm.put(k, String.valueOf(k));
        Integer f = tm.floorKey(q);
        return f == null ? -1 : f;
    }
}
